}
EOF
cat > $d/ValidateGradeAdd.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses adding a grade by a viewer, a code that is not one to three capital letters (once trimmed), or a
 *  grade the sheet already has. */
public class ValidateGradeAdd {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GradeAddRequest request,
            Out<GradeAddInput> body, RoleStore roles, GradeStore grades) throws InvalidSheetException {
        String sheet = sheetId.trim();
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheet, user);
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!GradeStore.CODE.matcher(grade).matches()) {
            throw new InvalidSheetException("A grade must be one to three capital letters");
        }
        if (grades.has(sheet, grade)) {
            throw new InvalidSheetException("The grade " + grade + " is already a grade");
        }
        body.set(new GradeAddInput(grade, user));
    }
}
EOF
cat > $d/SaveGradeAdded.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveGradeAdded {
    public void save(@PathVariable("sheetId") String sheetId, @Val GradeAddInput input, GradeStore grades) {
        grades.add(sheetId.trim(), input.grade());
    }
}
EOF
cat > $d/AuditGradeAdded.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Records a grade added: GRADE_ADDED sheet=<id> by=<user> grade=<grade>. */
public class AuditGradeAdded {
    public void audit(@PathVariable("sheetId") String sheetId, @Val GradeAddInput input, Audit audit) {
        audit.record("GRADE_ADDED sheet=" + sheetId.trim() + " by=" + input.user() + " grade=" + input.grade());
    }
}
EOF
cat > $d/RespondWithGradeAdded.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGradeAdded {
    public void respond(@Val GradeAddInput input, ObjectResponse<GradeResponse> response) {
        response.send(new GradeResponse(input.grade(), false));
    }
